def analyze(i):
    inp,out=d[i]['input'],d[i]['output']
    bg=6 if i==0 else 9
    pts=[(r,c,inp[r][c]) for r,row in enumerate(inp) for c,v in enumerate(row) if v!=bg]
    # blob = colors not equal to noise color
    noisecol=Counter(v for _,_,v in pts).most_common(1)[0][0]
    noise=[(r,c) for r,c,v in pts if v==noisecol]
    blob=[(r,c,v) for r,c,v in pts if v!=noisecol]
    r0=min(r for r,_,_ in blob);c0=min(c for _,c,_ in blob);r1=max(r for r,_,_ in blob);c1=max(c for _,c,_ in blob)
    H,W=r1-r0+1,c1-c0+1
    P=[[inp[r0+a][c0+b] if (r0+a,c0+b) in {(r,c) for r,c,_ in blob} else bg for b in range(W)] for a in range(H)]
    print('demo',i,'stamp',P,'noise',len(noise))
    offs=[]
    for r,c in noise:
        found=[]
        for dr in range(-H, H+1):
            for dc in range(-W, W+1):
                ok=True
                for a in range(H):
                    for b in range(W):
                        if P[a][b]!=bg:
                            rr,cc=r+dr+a,c+dc+b
                            if not(0<=rr<len(out) and 0<=cc<len(out[0])) or out[rr][cc]!=P[a][b]: ok=False;break
                    if not ok:break
                if ok: found.append((dr,dc))
        offs.append(((r,c),found))
    print(offs)
for i in range(3): analyze(i)

